def update_signature_args(sig: inspect.Signature, arg_types: Dict[str, type], has_self: bool, existing_annotation_strategy: ExistingAnnotationStrategy = ExistingAnnotationStrategy.REPLICATE) -> inspect.Signature:
    params = []
    for index, (name, param) in enumerate(sig.parameters.items()):
        if has_self and index == 0:
            params.append(param.replace(annotation=inspect.Parameter.empty))
            continue
        typ = arg_types.get(name)
        has_existing = param.annotation is not inspect.Parameter.empty
        if typ is None:
            if existing_annotation_strategy == ExistingAnnotationStrategy.IGNORE:
                params.append(param.replace(annotation=inspect.Parameter.empty))
            else:
                params.append(param)
        elif has_existing and existing_annotation_strategy == ExistingAnnotationStrategy.REPLICATE:
            params.append(param)
        elif has_existing and existing_annotation_strategy == ExistingAnnotationStrategy.OMIT:
            params.append(param.replace(annotation=inspect.Parameter.empty))
        else:
            params.append(param.replace(annotation=typ))
    return sig.replace(parameters=params)
